// src/components/WalletConnect.js
import React, { useState, useEffect, useCallback } from 'react';
import { BrowserProvider, formatEther } from 'ethers'; 
import detectEthereumProvider from '@metamask/detect-provider';

function WalletConnect({ onWalletConnected }) {
  const [account, setAccount] = useState(null);
  const [balance, setBalance] = useState(null);
  const [chainId, setChainId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [provider, setProvider] = useState(null);
  const [isMetaMaskInstalled, setIsMetaMaskInstalled] = useState(false);

  // Danh sách các mạng sử dụng ETH làm đơn vị gốc (Native Currency)
  const ETH_NETWORKS = {
    '0x1': { name: 'Ethereum Mainnet', color: '#627EEA' },
    '0xaa36a7': { name: 'Sepolia Testnet', color: '#CFADFF' },
    '0x4268': { name: 'Holešky Testnet', color: '#AA6DFF' },
    '0xa4b1': { name: 'Arbitrum One', color: '#28A0F0' },
    '0x66eee': { name: 'Arbitrum Sepolia', color: '#28A0F0' },
    '0xa': { name: 'Optimism Mainnet', color: '#FF0420' },
    '0xaa375': { name: 'Optimism Sepolia', color: '#FF0420' },
    '0x2105': { name: 'Base Mainnet', color: '#0052FF' },
    '0x14a34': { name: 'Base Sepolia', color: '#0052FF' },
    '0x539': { name: 'Local Hardhat', color: '#F39C12' },
    '0x7a69': { name: 'Local Anvil', color: '#F39C12' }
  };

  const updateWalletInfo = useCallback(async (newAccount, currentProvider) => {
    if (!newAccount || !currentProvider || !window.ethereum) {
      setAccount(null);
      setBalance(null);
      setChainId(null);
      if (onWalletConnected) onWalletConnected(null);
      return;
    }

    try {
      const currentChainId = await window.ethereum.request({ method: 'eth_chainId' });
      setChainId(currentChainId);

      // Kiểm tra ràng buộc chỉ dùng các mạng ETH
      if (!ETH_NETWORKS[currentChainId]) {
        setError("Mạng không hỗ trợ. Vui lòng chuyển sang mạng dùng ETH.");
        setBalance(null);
        if (onWalletConnected) onWalletConnected(null);
        return;
      }

      setError('');
      const balanceBigInt = await currentProvider.getBalance(newAccount);
      const formattedBalance = formatEther(balanceBigInt);
      
      setAccount(newAccount);
      setBalance(formattedBalance);

      if (onWalletConnected) {
        onWalletConnected({
          account: newAccount,
          balance: formattedBalance,
          chainId: currentChainId
        });
      }
    } catch (err) {
      console.error("Lỗi cập nhật ví:", err);
    }
  }, [onWalletConnected]);

  useEffect(() => {
    const init = async () => {
      const detectedProvider = await detectEthereumProvider();
      setIsMetaMaskInstalled(!!detectedProvider);

      if (detectedProvider) {
        const browserProvider = new BrowserProvider(detectedProvider);
        setProvider(browserProvider);

        const accounts = await detectedProvider.request({ method: 'eth_accounts' });
        if (accounts.length > 0) {
          updateWalletInfo(accounts[0], browserProvider);
        }

        const handleAccountsChanged = (accs) => updateWalletInfo(accs[0], browserProvider);
        const handleChainChanged = () => window.location.reload();

        detectedProvider.on('accountsChanged', handleAccountsChanged);
        detectedProvider.on('chainChanged', handleChainChanged);

        return () => {
          detectedProvider.removeListener('accountsChanged', handleAccountsChanged);
          detectedProvider.removeListener('chainChanged', handleChainChanged);
        };
      }
    };
    init();
  }, [updateWalletInfo]);

  const connectWallet = async () => {
    setError('');
    setLoading(true);
    try {
      if (!window.ethereum) throw new Error("Cài đặt MetaMask!");
      const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
      if (provider) await updateWalletInfo(accounts[0], provider);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const getNetworkDetails = (id) => {
    return ETH_NETWORKS[id] || { name: 'Mạng không hỗ trợ', color: '#ef4444' };
  };

  return (
    <div className="modern-wallet-card">
      <div className="glass-header">
        <div className="brand">
          <span className="brand-dot" style={{ backgroundColor: getNetworkDetails(chainId).color }}></span>
          <h2>Trạng thái ví</h2>
        </div>
        <span className={`status-badge ${isMetaMaskInstalled ? 'success' : 'error'}`}>
          {isMetaMaskInstalled ? 'Connected' : 'No Wallet'}
        </span>
      </div>

      <div className="wallet-body">
        {!account ? (
          <div className="disconnected-view">
            <div className="visual-container">
              <div className="glow-circle"></div>
              <span className="main-emoji">🦊</span>
            </div>
            <h3>Sẵn sàng kết nối</h3>
            <button onClick={connectWallet} disabled={loading} className="modern-btn primary">
              {loading ? "Đang xử lý..." : "Kết nối MetaMask"}
            </button>
            {error && <p className="error-text">⚠️ {error}</p>}
          </div>
        ) : (
          <div className="connected-view">
            {error ? (
              <div className="unsupported-network-overlay">
                <span className="error-icon">🚫</span>
                <h3>Mạng không hợp lệ</h3>
                <p>{error}</p>
                <div className="current-id-badge" style={{ marginTop: '10px', opacity: 0.7 }}>Chain ID: {chainId}</div>
              </div>
            ) : (
              <div className="bento-grid">
                <div className="bento-item account">
                  <span className="label">Địa chỉ ví</span>
                  <div className="value-row">
                    <span className="value">{account.slice(0, 6)}...{account.slice(-4)}</span>
                    <button onClick={() => navigator.clipboard.writeText(account)} className="copy-btn-modern">📋</button>
                  </div>
                </div>

                <div className="bento-item balance">
                  <span className="label">Số dư khả dụng</span>
                  <span className="value balance-text">
                    {parseFloat(balance).toFixed(4)} <small>ETH</small>
                  </span>
                </div>

                <div className="bento-item network">
                  <span className="label">Mạng hiện tại</span>
                  <div className="network-pill-trigger static" style={{ '--net-color': getNetworkDetails(chainId).color }}>
                    <span className="network-dot"></span>
                    <span className="network-name">{getNetworkDetails(chainId).name}</span>
                  </div>v
                </div>
              </div>
            )}

            <button onClick={() => setAccount(null)} className="modern-btn outline" style={{ marginTop: '20px' }}>
              Ngắt kết nối
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default WalletConnect;
